using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context with fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");

        // Breaking Change #1: Sync Cosmos queries removed in EF Core 9.
        // Synchronous I/O is no longer supported; all queries must be async.
        // If you absolutely need sync, use the workaround below (not recommended):
        // optionsBuilder.ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change #2: In EF Core 9 the Cosmos provider changed the
        // discriminator property name from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must explicitly configure
        // the old property name to avoid data compatibility issues.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Demonstrates the required async pattern for Cosmos queries in EF Core 9
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Breaking Change #1 fix: Convert sync queries to async.
    // EF Core 9 removed sync Cosmos support — ToList()/First()/Single() etc. throw.
    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }
}

