using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking Change #3: In EF Core 9, Migrate() can no longer be called
    // inside a manual transaction — it now manages its own transaction internally.
    // Wrapping it in BeginTransaction() throws InvalidOperationException.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

